use base64::{Engine, engine::general_purpose::STANDARD};
use runtrell_testkit::image_contracts::png;
pub fn encoded_output(format: &str) -> String {
    match format {
        "png" => STANDARD.encode(png()),
        // A local one-pixel red image, encoded with macOS sips / libwebp cwebp.
        "jpeg" => "".into(),
        "webp" => "UklGRhwAAABXRUJQVlA4TA8AAAAvAAAAAAcQ/Y/+ByKi/wEA".into(),
        _ => unreachable!(),
    }
}
